cudaStream_t s1, s2;
cudaStreamCreate(&s1); cudaStreamCreate(&s2);
cudaEvent_t e;
cudaEventCreate(&e);

// (1) Kernels launched on the same stream run in issued order:
kA<<<..., s1>>>(...);
kB<<<..., s1>>>(...);   // B waits for A on same stream

// (2) Cross-stream sync via events:
kC<<<..., s1>>>(...);
cudaEventRecord(e, s1);           // event fires when C completes on s1
cudaStreamWaitEvent(s2, e, 0);    // s2 stalls until e fires
kD<<<..., s2>>>(...);             // D on s2, ordered after C on s1

// (3) Default stream (0) behavior depends on --default-stream compile flag
